using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using PlatformHub.Api.Authorization;
using PlatformHub.Api.Platform;
using PlatformHub.Domain.Entities;
using PlatformHub.Infrastructure.Persistence;
namespace PlatformHub.Api.Controllers;
[ApiController] public sealed class BusinessModulesController(InventoryDbContext db,IActiveTenantContext scope):ControllerBase
{
 [HttpGet("api/stock/ledger")][RequireScopedPermission("Stock.Ledger.View")]
 public async Task<IActionResult> Ledger([FromQuery]long? productId,[FromQuery]long? storeId,[FromQuery]DateOnly? from,[FromQuery]DateOnly? to,CancellationToken ct){if(!S(out var t,out var b,out var p))return Forbid();var q=db.StockMovements.AsNoTracking().Where(x=>x.TenantId==t&&x.BranchId==b&&x.ProjectId==p);if(productId.HasValue)q=q.Where(x=>x.ProductId==productId);if(storeId.HasValue)q=q.Where(x=>x.StoreId==storeId);if(from.HasValue)q=q.Where(x=>x.TransactionUtc>=from.Value.ToDateTime(TimeOnly.MinValue));if(to.HasValue)q=q.Where(x=>x.TransactionUtc<to.Value.AddDays(1).ToDateTime(TimeOnly.MinValue));return Ok(await q.OrderBy(x=>x.TransactionUtc).ThenBy(x=>x.Id).Take(1000).Select(x=>new{x.Id,x.ProductId,x.StoreId,x.MovementType,x.QuantityIn,x.QuantityOut,x.UnitCost,x.ReferenceType,x.ReferenceId,x.TransactionUtc,x.Notes}).ToListAsync(ct));}
 [HttpPost("api/stock/movements")][RequireScopedPermission("Stock.Movement.Create")]
 public async Task<IActionResult> CreateMovement([FromBody]CreateStockMovementRequest r,CancellationToken ct){if(!S(out var t,out var b,out var p))return Forbid();if(r.ProductId<=0||r.StoreId<=0||r.QuantityIn<0||r.QuantityOut<0||(r.QuantityIn==0)==(r.QuantityOut==0)||r.UnitCost<0||string.IsNullOrWhiteSpace(r.MovementType))return BadRequest(new{message="Provide product/store/type, non-negative cost and exactly one positive quantity direction."});var prod=await db.InventoryItems.AnyAsync(x=>x.Id==r.ProductId&&x.IsActive&&x.TenantId==t&&x.BranchId==b&&x.ProjectId==p,ct);var store=await db.Stores.AnyAsync(x=>x.Id==r.StoreId&&x.IsActive&&x.TenantId==t&&x.BranchId==b&&x.ProjectId==p,ct);if(!prod||!store)return BadRequest(new{message="Product and store must belong to the active workspace."});var now=DateTime.UtcNow;var x=new StockMovement{TenantId=t,BranchId=b,ProjectId=p,ProductId=r.ProductId,StoreId=r.StoreId,MovementType=r.MovementType.Trim(),QuantityIn=r.QuantityIn,QuantityOut=r.QuantityOut,UnitCost=r.UnitCost,ReferenceType=string.IsNullOrWhiteSpace(r.ReferenceType)?"Manual":r.ReferenceType.Trim(),ReferenceId=r.ReferenceId,TransactionUtc=now,Notes=r.Notes?.Trim(),CreatedUtc=now,UpdatedUtc=now};db.StockMovements.Add(x);await db.SaveChangesAsync(ct);return Created($"/api/stock/ledger?productId={x.ProductId}&storeId={x.StoreId}",new{x.Id,x.ProductId,x.StoreId,x.MovementType,x.QuantityIn,x.QuantityOut,x.UnitCost,x.TransactionUtc});}
 [HttpGet("api/stock/stores")][RequireScopedPermission("Stock.Store.View")]
 public async Task<IActionResult> Stores(CancellationToken ct){if(!S(out var t,out var b,out var p))return Forbid();return Ok(await db.Stores.AsNoTracking().Where(x=>x.IsActive&&x.TenantId==t&&x.BranchId==b&&x.ProjectId==p).OrderBy(x=>x.Name).Select(x=>new{x.Id,x.Code,x.Name,x.Address}).ToListAsync(ct));}
 [HttpPost("api/stock/stores")][RequireScopedPermission("Stock.Store.Create")]
 public async Task<IActionResult> CreateStore([FromBody]SaveStoreRequest r,CancellationToken ct){if(!S(out var t,out var b,out var p))return Forbid();var code=r.Code?.Trim();var name=r.Name?.Trim();if(string.IsNullOrWhiteSpace(code)||code.Length>50||string.IsNullOrWhiteSpace(name)||name.Length>150)return BadRequest(new{message="Store code (max 50) and name (max 150) are required."});if(await db.Stores.AnyAsync(x=>x.TenantId==t&&x.BranchId==b&&x.ProjectId==p&&x.Code==code,ct))return Conflict(new{message="Store code already exists in this workspace."});var now=DateTime.UtcNow;var x=new InventoryStore{TenantId=t,BranchId=b,ProjectId=p,Code=code,Name=name,Address=r.Address?.Trim(),CreatedUtc=now,UpdatedUtc=now};db.Stores.Add(x);await db.SaveChangesAsync(ct);return Created($"/api/stock/stores/{x.Id}",new{x.Id,x.Code,x.Name,x.Address});}
 [HttpGet("api/accounting/accounts")][RequireScopedPermission("Accounting.Account.View")]
 public async Task<IActionResult> Accounts(CancellationToken ct){if(!S(out var t,out var b,out var p))return Forbid();return Ok(await db.AccountHeads.AsNoTracking().Where(x=>x.IsActive&&x.TenantId==t&&x.BranchId==b&&x.ProjectId==p).OrderBy(x=>x.Code).Select(x=>new{x.Id,x.Code,x.Name,x.AccountType,x.ParentAccountId,x.IsControlAccount}).ToListAsync(ct));}
 [HttpGet("api/accounting/vouchers")][RequireScopedPermission("Accounting.Voucher.View")]
 public async Task<IActionResult> Vouchers([FromQuery]DateOnly? from,[FromQuery]DateOnly? to,CancellationToken ct){if(!S(out var t,out var b,out var p))return Forbid();var q=db.AccountingVouchers.AsNoTracking().Where(x=>x.IsActive&&x.TenantId==t&&x.BranchId==b&&x.ProjectId==p);if(from.HasValue)q=q.Where(x=>x.VoucherDate>=from);if(to.HasValue)q=q.Where(x=>x.VoucherDate<=to);return Ok(await q.OrderByDescending(x=>x.VoucherDate).Take(500).Select(x=>new{x.Id,x.VoucherNo,x.VoucherType,x.VoucherDate,x.Status,x.TotalDebit,x.TotalCredit,x.PostedUtc,x.Narration}).ToListAsync(ct));}
 [HttpGet("api/business-documents")][RequireScopedPermission("BusinessDocument.View")]
 public async Task<IActionResult> Documents([FromQuery]string? type,[FromQuery]DateOnly? from,[FromQuery]DateOnly? to,CancellationToken ct){if(!S(out var t,out var b,out var p))return Forbid();var q=db.BusinessDocuments.AsNoTracking().Where(x=>x.IsActive&&x.TenantId==t&&x.BranchId==b&&x.ProjectId==p);if(!string.IsNullOrWhiteSpace(type))q=q.Where(x=>x.DocumentType==type.Trim());if(from.HasValue)q=q.Where(x=>x.DocumentDate>=from);if(to.HasValue)q=q.Where(x=>x.DocumentDate<=to);return Ok(await q.OrderByDescending(x=>x.DocumentDate).Take(500).Select(x=>new{x.Id,x.DocumentType,x.DocumentNo,x.DocumentDate,x.PartyName,x.Status,x.TotalAmount}).ToListAsync(ct));}
 bool S(out long t,out long? b,out long? p){t=scope.TenantId.GetValueOrDefault();b=scope.BranchId;p=scope.ProjectId;return scope.IsResolved&&t>0;}
}
public sealed record CreateStockMovementRequest(long ProductId,long StoreId,string MovementType,decimal QuantityIn,decimal QuantityOut,decimal UnitCost,string? ReferenceType=null,long? ReferenceId=null,string? Notes=null);
public sealed record SaveStoreRequest(string? Code,string? Name,string? Address=null);
